UPDATE produtos AS produto
SET
    corredor = dados.corredor,
    prateleira = dados.prateleira
FROM dados
WHERE TRIM(produto.codigo) = dados.codigo
  AND UPPER(TRIM(produto.origem)) = UPPER(dados.origem);

